-- app/migrations/2026-11-27_task_seed_4.sql: the goals as parent tasks, each with its owner (decisions/0180's appendix), measure,
-- due date and decision, then the open items since Nov 25 as their children (CLAUDE.md #1552, Jason 2026-11-27). Data only, no CREATE.
-- Every id is named (MAX(id)+1, guarded by NOT EXISTS): staging's copied tables have AUTO_INCREMENT behind their rows (until 0165's fix).
-- Nothing that exists is created again: a task is matched by (gauge, item), and existing tasks only gain a parent where they have none.
SET @s = (SELECT IF(COUNT(*) = 0, 'ALTER TABLE control_gauge_tasks ADD COLUMN due_on DATE NULL', 'DO 0') FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'control_gauge_tasks' AND COLUMN_NAME = 'due_on');
PREPARE q FROM @s;
EXECUTE q;
DEALLOCATE PREPARE q;
SET @s = (SELECT IF(COUNT(*) = 0, 'ALTER TABLE control_gauge_tasks ADD COLUMN measure VARCHAR(255) NULL', 'DO 0') FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'control_gauge_tasks' AND COLUMN_NAME = 'measure');
PREPARE q FROM @s;
EXECUTE q;
DEALLOCATE PREPARE q;
SET @n = (SELECT COALESCE(MAX(id), 0) + 1 FROM control_gauge_tasks);
SET @p = NULL;
INSERT INTO control_gauge_tasks (id, at, tz, gauge, item, kind, what, bucket, value, who, uid, why, source, owner, owner_at, goal, in_scope, out_scope, done_when, priority, ticket, stage, stage_at, tier, parent_id) SELECT @n, UTC_TIMESTAMP(), '', 'area:goals', 'Goals and records with the roles, live by Mon Nov 30 13:00 UTC', 'fix', 'Goals and records with the roles, live by Mon Nov 30 13:00 UTC', 'task', '', 'task-seed-4 (Build & QA, 21)', 0, 'Jason, 2026-11-27: "Yes, approve the plan… up and running by Monday morning 6 am". No goal, ruling or order lives only in a session.', 'CLAUDE.md "Goals and records live with the roles" (#1552), recorded as Operations & Policy (16)', 'Chief Executive Officer (2)', UTC_TIMESTAMP(), 'Each long-term goal is a parent task with an owner from 0180''s appendix, a measure, a due date and its decision, and every ticket links to its goal', NULL, NULL, 'Measure: every goal is a parent task on live with owner, measure, due and decision, and every open ticket has a goal. Due: Mon Nov 30, 2026 13:00 UTC (06:00 MST)', 1, 'work', 'planning', UTC_TIMESTAMP(), NULL, @p FROM DUAL WHERE NOT EXISTS (SELECT id FROM control_gauge_tasks WHERE kind = 'fix' AND gauge = 'area:goals' AND item = 'Goals and records with the roles, live by Mon Nov 30 13:00 UTC' ORDER BY id LIMIT 1);
SET @a = (SELECT COALESCE(MAX(id), 0) + 1 FROM control_gauge_task_adrs);
SET @t = (SELECT id FROM control_gauge_tasks WHERE kind = 'fix' AND gauge = 'area:goals' AND item = 'Goals and records with the roles, live by Mon Nov 30 13:00 UTC' ORDER BY id LIMIT 1);
